class Solution:
    def cherryPickup(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        dp = [[-1] * cols for _ in range(cols)]
        dp[0][cols - 1] = grid[0][0] + (grid[0][cols - 1] if cols > 1 else 0)
        for r in range(1, rows):
            nxt = [[-1] * cols for _ in range(cols)]
            for c1 in range(cols):
                for c2 in range(cols):
                    if dp[c1][c2] == -1:
                        continue
                    for d1 in (-1, 0, 1):
                        nc1 = c1 + d1
                        if not (0 <= nc1 < cols):
                            continue
                        for d2 in (-1, 0, 1):
                            nc2 = c2 + d2
                            if not (0 <= nc2 < cols):
                                continue
                            cherries = grid[r][nc1] if nc1 == nc2 else grid[r][nc1] + grid[r][nc2]
                            nxt[nc1][nc2] = max(nxt[nc1][nc2], dp[c1][c2] + cherries)
            dp = nxt
        return max(max(row) for row in dp)
