class Solution {
public:
    int cherryPickup(vector<vector<int>>& grid) {
        int rows = grid.size(), cols = grid[0].size();
        vector<vector<int>> dp(cols, vector<int>(cols, -1));
        dp[0][cols - 1] = grid[0][0] + (cols > 1 ? grid[0][cols - 1] : 0);
        for (int r = 1; r < rows; ++r) {
            vector<vector<int>> nxt(cols, vector<int>(cols, -1));
            for (int c1 = 0; c1 < cols; ++c1) {
                for (int c2 = 0; c2 < cols; ++c2) {
                    if (dp[c1][c2] == -1) continue;
                    for (int d1 = -1; d1 <= 1; ++d1) {
                        int nc1 = c1 + d1;
                        if (nc1 < 0 || nc1 >= cols) continue;
                        for (int d2 = -1; d2 <= 1; ++d2) {
                            int nc2 = c2 + d2;
                            if (nc2 < 0 || nc2 >= cols) continue;
                            int cherries = (nc1 == nc2) ? grid[r][nc1] : grid[r][nc1] + grid[r][nc2];
                            nxt[nc1][nc2] = max(nxt[nc1][nc2], dp[c1][c2] + cherries);
                        }
                    }
                }
            }
            dp = move(nxt);
        }
        int res = 0;
        for (int c1 = 0; c1 < cols; ++c1) {
            for (int c2 = 0; c2 < cols; ++c2) {
                res = max(res, dp[c1][c2]);
            }
        }
        return res;
    }
};

class Solution {
    public int cherryPickup(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int[][] dp = new int[cols][cols];
        for (int[] row : dp) Arrays.fill(row, -1);
        dp[0][cols - 1] = grid[0][0] + (cols > 1 ? grid[0][cols - 1] : 0);
        for (int r = 1; r < rows; r++) {
            int[][] nxt = new int[cols][cols];
            for (int[] row : nxt) Arrays.fill(row, -1);
            for (int c1 = 0; c1 < cols; c1++) {
                for (int c2 = 0; c2 < cols; c2++) {
                    if (dp[c1][c2] == -1) continue;
                    for (int d1 = -1; d1 <= 1; d1++) {
                        int nc1 = c1 + d1;
                        if (nc1 < 0 || nc1 >= cols) continue;
                        for (int d2 = -1; d2 <= 1; d2++) {
                            int nc2 = c2 + d2;
                            if (nc2 < 0 || nc2 >= cols) continue;
                            int cherries = (nc1 == nc2) ? grid[r][nc1] : grid[r][nc1] + grid[r][nc2];
                            nxt[nc1][nc2] = Math.max(nxt[nc1][nc2], dp[c1][c2] + cherries);
                        }
                    }
                }
            }
            dp = nxt;
        }
        int res = 0;
        for (int c1 = 0; c1 < cols; c1++) {
            for (int c2 = 0; c2 < cols; c2++) {
                res = Math.max(res, dp[c1][c2]);
            }
        }
        return res;
    }
}

var cherryPickup = function(grid) {
    const rows = grid.length, cols = grid[0].length;
    let dp = Array.from({ length: cols }, () => new Array(cols).fill(-1));
    dp[0][cols - 1] = grid[0][0] + (cols > 1 ? grid[0][cols - 1] : 0);
    for (let r = 1; r < rows; r++) {
        const nxt = Array.from({ length: cols }, () => new Array(cols).fill(-1));
        for (let c1 = 0; c1 < cols; c1++) {
            for (let c2 = 0; c2 < cols; c2++) {
                if (dp[c1][c2] === -1) continue;
                for (let d1 = -1; d1 <= 1; d1++) {
                    const nc1 = c1 + d1;
                    if (nc1 < 0 || nc1 >= cols) continue;
                    for (let d2 = -1; d2 <= 1; d2++) {
                        const nc2 = c2 + d2;
                        if (nc2 < 0 || nc2 >= cols) continue;
                        const cherries = (nc1 === nc2) ? grid[r][nc1] : grid[r][nc1] + grid[r][nc2];
                        nxt[nc1][nc2] = Math.max(nxt[nc1][nc2], dp[c1][c2] + cherries);
                    }
                }
            }
        }
        dp = nxt;
    }
    let res = 0;
    for (let c1 = 0; c1 < cols; c1++) {
